import{_ as o,l as n,o as e,c as l,v as r,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Zernike 漂移与操纵器","description":"","frontmatter":{"title":"Zernike 漂移与操纵器","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/aberration-manipulators.md","filePath":"litho/aberration-manipulators.md","lastUpdated":1789023840000}'),E={name:"litho/aberration-manipulators.md"};function _(c,a,m,A,u,k){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="zernike-漂移与操纵器" tabindex="-1">Zernike 漂移与操纵器 <a class="header-anchor" href="#zernike-漂移与操纵器" aria-label="Permalink to &quot;Zernike 漂移与操纵器&quot;">​</a></h1><div class="epigraph"><p>热、气压、装调残差让 Zernike 系数慢慢走。操纵器是镜头里的可动自由度，把可观测量推回预算，不是把设计改成另一台镜头。</p><footer>—— 对照投影物镜 manipulator；[Zernike 像差](/litho/zernike-aberrations)</footer></div><p><a href="/litho/lens-heating-compensation">上一课</a>给出热前馈。缺口是执行器：哪些面可以微动、能动哪些项。本课钉操纵器，计量方法留给后课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>系数空间维数高于执行器数。能补球差、像散，未必能补高阶或非旋转对称的加工残差。乱拧会把一套项拧进另一套。把「镜头可调」理解成任意波前整形，会高估 SMO 闭环。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开层面：若干透镜间隔/倾斜、可能的变形镜或主动支撑。控制把量测（相位测量、晶圆上像差探针）映射到执行器命令，用伪逆，正则化避免增益过大。与加热表叠加：热前馈 + 操纵器反馈。</p>',7)),(e(),s(h,null,{default:t(()=>[p(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEAS%5B%22%E5%83%8F%E5%B7%AE%E9%87%8F%E6%B5%8B%22%5D%20--%3E%20MAP%5B%22%E6%89%A7%E8%A1%8C%E5%99%A8%E6%98%A0%E5%B0%84%22%5D%0A%20%20HEAT%5B%22%E5%8A%A0%E7%83%AD%E5%89%8D%E9%A6%88%22%5D%20--%3E%20MAP%0A%20%20MAP%20--%3E%20ACT%5B%22%E9%97%B4%E9%9A%94%20%2F%20%E5%80%BE%E6%96%9C%22%5D%0A%20%20ACT%20--%3E%20Z%5B%22Zernike%20%E6%AE%8B%E5%B7%AE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p><span class="marginnote">扫描缝视场上像差还随缝内位置变。操纵器通常补的是缝平均或低阶场依赖，不是每个点独立。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>透镜微移改变局部光焦度与偏心，在光瞳上近似低阶 Zernike。高阶项对间隔不敏感，要靠加工和热管理，不能靠拧螺丝。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课致密化：永久材料变化，操纵器行程会慢慢被吃掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>操纵器补可观测的低阶 Zernike，维数有限。</li><li>与加热前馈叠加；不能当任意波前整形。</li><li>出处：Zernike 课；物镜 manipulator 通识。</li></ul>',7))])}const T=o(E,[["render",_]]);export{b as __pageData,T as default};
